      "title": "ポーランド軍の弾圧とゴムウカ",
      "body": [
        "それに、ポーランドにはこれまで抑圧されてきたロシア（ソ連）に対する恨みもある！ ただ、ポーランド政府は「これじゃあソ連軍に<ruby>潰<rt>つぶ</rt></ruby>される！」って思って、<strong class=\"source-bold\">ポーランド軍を出動して<ruby>弾圧<rt>だんあつ</rt></ruby></strong>したから、余計に民主化運動が激化、改革派だった<strong class=\"source-bold\">ゴムウカ</strong>が第一書記に復活したよ。"
      ],
      "plainBody": [
        "それに、ポーランドにはこれまで抑圧されてきたロシア（ソ連）に対する恨みもある！ ただ、ポーランド政府は「これじゃあソ連軍に潰される！」って思って、ポーランド軍を出動して弾圧したから、余計に民主化運動が激化、改革派だったゴムウカが第一書記に復活したよ。"
      ],
