      "title": "進歩のための同盟",
      "body": [
        "ケネディは<strong class=\"source-bold\">キューバとの断交の方針を変えず</strong>、ラテンアメリカ諸国への経済援助を通じてキューバ革命の波及を阻止する、事実上の反共（反共産主義）同盟<strong class=\"source-bold\">「進歩のための同盟」</strong>を打ち出した。"
      ],
