      "title": "ローマ条約と二つの共同体",
      "body": [
        " こうしてECSCを構成する6カ国は、さらに経済統合を進めるための交渉をおこない、1957年には<strong class=\"source-bold\">ローマ条約</strong>を結んで、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ヨーロッパ原子力共同体</strong></span> <strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">EURATOM</strong></span>】</strong>と<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ヨーロッパ経済共同体</strong></span> <strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">EEC</strong></span>】</strong>の創設を決め、<strong class=\"source-bold\">翌年に発足</strong>した。"
      ],
