      "id": "modern-c05-l21-p04-015",
      "title": "北爆の開始とベトナム戦争",
      "body": [
        "こうなると、核保有国になった<strong class=\"source-bold\">中国が確実にアジアで影響力を伸ばしてくる</strong>。「ベトナムに本格介入しないと、アジアでのアメリカの威信が大きく揺らぐ」と焦ったジョンソンは、ついに1965年2月<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">北ベトナムへの爆撃</strong></span> <strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>北爆<rt>ほくばく</rt></ruby></strong></span>】</strong>を開始した。こうしてアメリカは<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ベトナム戦争</strong></span>へと突入したんだ。"
      ],
      "plainBody": [
        "こうなると、核保有国になった中国が確実にアジアで影響力を伸ばしてくる。「ベトナムに本格介入しないと、アジアでのアメリカの威信が大きく揺らぐ」と焦ったジョンソンは、ついに1965年2月北ベトナムへの爆撃 【北爆】を開始した。こうしてアメリカはベトナム戦争へと突入したんだ。"
      ],
