      "title": "中国の対仏接近と公開論争",
      "body": [
        "さらに<strong class=\"source-bold\">部分的<ruby>核<rt>かく</rt></ruby>実験禁止条約</strong>が<ruby>締結<rt>ていけつ</rt></ruby>されると、中国は「米ソによる中国<ruby>封<rt>ふう</rt></ruby>じ込めだ」と、同じく米ソに対抗して<strong class=\"source-bold\">独自の核開発を進めるフランスに接近</strong>したから、これまで隠されてきた<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">中ソ対立</strong></span>は<strong class=\"source-bold\">公開論争</strong>となり、ついに全世界に知れわたった。"
      ],
