      "title": "ドプチェクの人間の顔をした社会主義",
      "body": [
        "1月に第一書記となった<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ドプチェク</strong></span>は<strong class=\"source-bold\">「人間の顔をした社会主義」</strong>を打ち出して、<ruby>検閲<rt>けんえつ</rt></ruby>の廃止・言論の自由化などの民主化を進めたから、チェコスロヴァキアでは共産党以外の政党をつくる動きが起きたり、西欧文化の流入でミニスカートで歩く若者まで現れた。"
      ],
      "plainBody": [
        "1月に第一書記となったドプチェクは「人間の顔をした社会主義」を打ち出して、検閲の廃止・言論の自由化などの民主化を進めたから、チェコスロヴァキアでは共産党以外の政党をつくる動きが起きたり、西欧文化の流入でミニスカートで歩く若者まで現れた。"
      ],
