      "id": "modern-c05-l21-p04-061",
      "title": "五カ国の軍事介入",
      "body": [
        "ついにブレジネフの怒りが爆発した。1968年8月、50万人にものぼる<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ソ連</strong></span><strong class=\"source-bold\">・東ドイツ・ポーランド・ハンガリー・ブルガリア</strong>5カ国の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ワルシャワ条約機構軍</strong></span>は<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">チェコスロヴァキアに軍事<ruby>介入<rt>かいにゅう</rt></ruby></strong></span>した（<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">チェコ事件</strong></span>）。"
      ],
