        "ついにブレジネフの怒りが爆発した。1968年8月、50万人にものぼるソ連・東ドイツ・ポーランド・ハンガリー・ブルガリア5カ国のワルシャワ条約機構軍はチェコスロヴァキアに軍事介入した（チェコ事件）。"
