export const sourcePages = {
  "384": "<h2>384</h2>\n<h1><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第21回</strong></span> <span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">冷戦の展開②（1956〜1969）</span></h1>\n<p>それじゃあ、<ruby>冷戦<rt>れいせん</rt></ruby>の2回目だよ。前回は「<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">雪どけ</u>」と「<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">巻き返し政策</u>」が同時期に進んでいたけど、どっちに進むかわからなかったよね。いったい世界はどっちに向かうんだろう？</p>\n<h3><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">大きくつかもう！</span></h3>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td><td></td><td></td></tr><tr><td><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">1</span></td><td><strong class=\"source-bold\">スターリン批判と平和共存政策</strong></td><td><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\">385〜387ページ</span></td></tr><tr><td><span data-source-color=\"red\" style=\"color:#e52715\">⬇</span></td><td></td><td></td></tr><tr><td><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">2</span></td><td><strong class=\"source-bold\">冷戦の再燃とキューバ危機</strong></td><td><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\">387〜390ページ</span></td></tr><tr><td><span data-source-color=\"red\" style=\"color:#e52715\">⬇</span></td><td></td><td></td></tr><tr><td><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">4</span></td><td><strong class=\"source-bold\">東西両陣営の動揺</strong></td><td><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\">395〜401ページ</span></td></tr></tbody></table></div>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td><td></td><td></td></tr><tr><td><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">3</span></td><td><strong class=\"source-bold\">ECの成立と西欧諸国</strong></td><td><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\">390〜394ページ</span></td></tr></tbody></table></div>\n<blockquote><p>米ソ両大国の関係は「雪どけ」↓「対立」↓「対話の模索」ってイメージだ</p></blockquote>\n<p><u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">スターリンの死</u>後、ソ連の態度がちょっとだけ対話へと向かい、1956年からさらに「雪どけ」が進むよ。フルシチョフによる「<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">スターリン批判</u>」は世界を驚かせ、「<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">平和共存</u>」で米ソが対話を始めたんだけど、それも長くは続かなかった。再び対立が激化して、<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">キューバ危機</u>で対立はピークに達した。同じころ、資本主義陣営では<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">フランスが米英に反抗</u>し、社会主義陣営でもソ連と中国が対立する<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">中ソ論争</u>が起きて体制が動揺した。こうして世界は米ソ両国と、それに対抗する動きから<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">多極化</u>の時代に進むんだ。</p>\n<p>それじゃあ冷戦の第2回、いってみよう〜。</p>",
  "385": "<h2>385</h2>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">1</span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">スターリン批判と平和共存政策</u> 385</p></blockquote>\n<h3><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">1</span> <span data-source-background=\"pink\" data-source-border=\"red\" style=\"background-color:#f7caca;border:1px solid #e52715;padding:0 0.2em\"><strong class=\"source-bold\">スターリン批判と平和共存政策</strong></span></h3>\n<h3><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">クローズアップ</strong></span> <span data-source-background=\"pink\" style=\"background-color:#fbe1e1\"><strong class=\"source-bold\">平和共存政策と米ソ関係［1956〜63］</strong></span></h3>\n<div class=\"source-table-wrap\"><table><tbody><tr><td>〈西側（資本主義）陣営〉</td><td>〈東側（共産主義）陣営〉</td></tr><tr><td><span data-source-color=\"green\" style=\"color:#315837\">●</span>米：<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">アイゼンハワー</strong></span>大統領<br>［在1953〜61］</td><td><span data-source-color=\"green\" style=\"color:#315837\">●</span>ソ連：<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">フルシチョフ</strong></span>、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">スターリン批判</strong></span>［1956.2］</td></tr><tr><td><u data-source-underline-color=\"red\" data-source-underline-style=\"double\" style=\"text-decoration-color:#e52715;text-decoration-style:double\"><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">平和共存政策</strong></span></u></td><td><span data-source-color=\"green\" style=\"color:#315837\">➡</span>共産圏の動揺<br><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ポーランド反政府反ソ暴動</strong></span><br><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ハンガリー反ソ暴動</strong></span><br><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">中ソ対立</strong></span>の開始</td></tr><tr><td><span data-source-color=\"green\" style=\"color:#315837\">➡</span>「<u data-source-underline-color=\"gray\" data-source-underline-style=\"double\" style=\"text-decoration-color:#777777;text-decoration-style:double\">雪どけ</u>」<br><span data-source-color=\"red\" style=\"color:#e52715\">⬇</span></td><td></td></tr><tr><td><span data-source-border=\"black\" style=\"border:1px solid #001000;padding:0 0.2em\"><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">日ソ共同宣言</strong></span>［1956.10］</span></td><td></td></tr><tr><td>※西欧の統合推進＝<strong class=\"source-bold\">ローマ条約</strong><br><span data-source-color=\"green\" style=\"color:#315837\">➡</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">EEC</strong></span>、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">EURATOM</strong></span>結成</td><td>※<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">キューバ革命</strong></span>［1959.1］</td></tr><tr><td><span data-source-border=\"black\" style=\"border:1px solid #001000;padding:0 0.2em\"><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">フルシチョフ訪米</strong></span>［1959.9］</span></td><td><u data-source-underline-color=\"gray\" data-source-underline-style=\"double\" style=\"text-decoration-color:#777777;text-decoration-style:double\">キューバ社会主義宣言</u></td></tr><tr><td><span data-source-color=\"green\" style=\"color:#315837\">●</span>米：<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ケネディ</strong></span>大統領就任［1961.1］</td><td>※「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ベルリンの壁</strong></span>」建設［1961.8］<br><span data-source-color=\"red\" style=\"color:#e52715\">⬅</span></td></tr><tr><td><span data-source-border=\"black\" style=\"border:1px solid #001000;padding:0 0.2em\"><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">キューバ危機</strong></span>［1962］</span></td><td></td></tr><tr><td><span data-source-border=\"black\" style=\"border:1px solid #001000;padding:0 0.2em\"><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">部分的核実験禁止条約</strong></span>［1963］</span></td><td></td></tr></tbody></table></div>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">◀ スターリン批判と平和共存政策で社会主義陣営が動揺！</strong></span></h4>\n<p>ジュネーヴ4巨頭会談に出席したソ連の首相はブルガーニンだったけど、実際に権力を握っていたのは<strong class=\"source-bold\">共産党の第一書記</strong>として後ろに控えていた<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">フルシチョフ</strong></span>だ。そして、この会議で権威を高めたフルシチョフは、1956年の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ソ連共産党第20回大会</strong></span>で「スターリンがやってきた個人<ruby>崇拝<rt>すうはい</rt></ruby>や反対派の大量<ruby>粛清<rt>しゅくせい</rt></ruby>は間違っていた」という秘密報告をおこなうと（<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">スターリン批判</strong></span>）、さらにスターリンの「資本主義国は全滅させる」という外交方針をやめて、<strong class=\"source-bold\">「社会主義国と資本主義国が平和に共存すれば、世界戦争は回避できる」</strong>という<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">平和共存政策</strong></span>へと転換したんだ。これは、もし<ruby>核<rt>かく</rt></ruby>戦争が起きたら世界が全滅するという<strong class=\"source-bold\">「恐怖の<ruby>均衡<rt>きんこう</rt></ruby>」</strong>が背景だよ。</p>\n<p>スターリン批判を受けて、ソ連の国内では<strong class=\"source-bold\">国家の締めつけをゆるめて</strong>活発な議論を認めたり（もちろんかなり部分的にだけどさ……）、国家の権限を地方（各共和国や州など）に移すなどの改革が始まったんだけど、同時にスターリン批判を通じて<strong class=\"source-bold\">フルシチョフが最高指導者</strong>の地位を固めたんだ。</p>\n<p>一方で、フルシチョフのスターリン批判は、<strong class=\"source-bold\">東欧諸国の共産党支配を弱める</strong>結果になった。1956年、平和共存政策に基づいて<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">コミンフォルムが解散</strong></span>されると、東欧</p>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">国民国家の形成</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">帝国主義と第一次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦間期と第二次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">戦後の世界</strong></span></p></blockquote>",
  "386": "<h2>386</h2>\n<blockquote><p>386 <span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第21回</strong></span> 冷戦の展開②（1956〜1969）</p></blockquote>\n<p>の人びとの間に<strong class=\"source-bold\">自由化への期待が高まった</strong>んだ。「もしかして、ソ連の言うことを聞かなくていいのでは？ だったら、ウチの国の共産党の言うことも聞かなくていいじゃん！」ってね。こうして、<strong class=\"source-bold\">各国で反政府暴動が起きた</strong>んだ。</p>\n<p>まずは<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ポーランド反政府反ソ暴動</strong></span> <strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ポズナニ暴動</strong></span>】</strong>だ。1956年、ポーランド西部の<strong class=\"source-bold\">ポズナニ</strong>で、<strong class=\"source-bold\">労働者や学生が政治・経済の改革を要求</strong>して暴動を起こした。それに、ポーランドにはこれまで抑圧されてきたロシア（ソ連）に対する恨みもある！ ただ、ポーランド政府は「これじゃあソ連軍に<ruby>潰<rt>つぶ</rt></ruby>される！」って思って、<strong class=\"source-bold\">ポーランド軍を出動して<ruby>弾圧<rt>だんあつ</rt></ruby></strong>したから、余計に民主化運動が激化、改革派だった<strong class=\"source-bold\">ゴムウカ</strong>が第一書記に復活したよ。ゴムウカは、農村の改革や宗教の自由などの<strong class=\"source-bold\">独自路線</strong>をとることを約束して暴動を抑えたんだけど、同時にソ連から乗り込んできたフルシチョフには、「ポーランドは<strong class=\"source-bold\">ソ連の忠実な同盟国</strong>である」と約束した。こうして「自主解決」したから、<strong class=\"source-bold\">ポーランドにはソ連軍は<ruby>介入<rt>かいにゅう</rt></ruby>していない</strong>よ。</p>\n<p>一方で、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ハンガリー反ソ暴動</strong></span> <strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ハンガリー事件</strong></span>】</strong>はひどいもんだよ。首都<strong class=\"source-bold\">ブダペスト</strong>の学生や労働者を中心に<strong class=\"source-bold\">民主化を求める大規模なデモ</strong>が起きると、改革派の<strong class=\"source-bold\">ナジ【ナジ＝イムレ】</strong>が首相に復帰し、「<strong class=\"source-bold\">ワルシャワ条約機構から脱退する</strong>」と言い出した。これにはフルシチョフも我慢ならず、<strong class=\"source-bold\">ソ連軍をハンガリーに送って</strong>数千人を殺害！。徹底的に弾圧した。ちょうど、英仏がスエズ戦争をやっていて、世界的に目立たなかったからね。こうして、<strong class=\"source-bold\">ナジはソ連軍に逮捕・処刑</strong>され、親ソ派の<strong class=\"source-bold\">カーダール</strong>が政権に<ruby>就<rt>つ</rt></ruby>いた。ていうか、一国の首相を捕まえて処刑するなんて、あり得ないよ。</p>\n<p>そして、このころから<strong class=\"source-bold\">中国とソ連の関係がギクシャクし始めた</strong>んだ。中国では<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>毛<rt>もう</rt></ruby><ruby>沢東<rt>たくとう</rt></ruby></strong></span>がスターリンと同じように「<strong class=\"source-bold\">個人<ruby>崇拝<rt>すうはい</rt></ruby></strong>」をさせてるから、スターリン批判の影響で、<strong class=\"source-bold\">自分の個人崇拝が批判される</strong>かもしれないでしょ。しかも、ソ連は社会主義建設がほぼ終わっているけど、中国はとにかく急激な社会主義化を進めたい。しかも、中心は農民！ だって、中国って農民が多いじゃん。だから、重化学工業を重視した<strong class=\"source-bold\">ソ連型の社会主義は中国にはあわなかった</strong>。でも、中国を援助してるソ連はおもしろくない。こうして<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">中ソ対立</strong></span>が始まったんだ。</p>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">◀ ソ連の平和共存政策で、ついに米ソ首脳会談も実現！</strong></span></h4>\n<p>一方、西側との「平和共存」は進むよ。ソ連がまず関係を改善したのが日本だ。ソ連は日本と西側諸国が結んだ<strong class=\"source-bold\">サンフランシスコ平和条約に調印しなかった</strong>よね。ってことは、日本とソ連は法的にはまだ戦争中……。北方領土問題があったから、なかなか調整がつかなかったんだけど、ついに1956年、日本の首相<strong class=\"source-bold\"><ruby>鳩山一郎<rt>はとやまいちろう</rt></ruby></strong>とソ連首相<strong class=\"source-bold\">ブルガーニン</strong>が<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">日ソ共同宣言</strong></span>に調印して正式に戦争を終わらせ、<strong class=\"source-bold\">国交を回復</strong>したよ。ただ、<strong class=\"source-bold\">北方領土問題は棚上げ</strong>。この問題は現在まで未解決だね。そして、ソ連と国交を回復したから<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">日本の国連加盟</strong></span>が実現したんだ。</p>\n<p>そして、ソ連の平和共存政策によって「雪どけ」が進み、ついに米ソ首脳会談が実現することになった。ただね……これにはウラもあるんだよ。1957年、ソ連</p>",
  "387": "<h2>387</h2>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">2</span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">冷戦の再燃とキューバ危機</u> 387</p></blockquote>\n<p>は<strong class=\"source-bold\">史上初の大陸間弾道弾【ICBM】</strong>、要するに<strong class=\"source-bold\">ミサイルの打ち上げに成功</strong>して、さらに同じ年には<strong class=\"source-bold\">人工衛星スプートニク1号</strong>の打ち上げにも成功した。これって、人工衛星のかわりに<ruby>原爆<rt>げんばく</rt></ruby>とか<ruby>水爆<rt>すいばく</rt></ruby>を積めば、<strong class=\"source-bold\">ソ連がアメリカ本土を直接<ruby>核<rt>かく</rt></ruby>兵器で攻撃できる</strong>ってことだ！ しかも、これに対抗してアメリカがおこなった人工衛星の打ち上げが失敗……。これに、アメリカはとんでもないショックを受けた（<strong class=\"source-bold\">スプートニク＝ショック</strong>）。これまで、<strong class=\"source-bold\">原爆も水爆もアメリカがソ連より早く開発</strong>してきたけど、<strong class=\"source-bold\">ミサイル開発ではソ連に先行されて</strong>、アメリカの軍事的な優位が崩れたようにも見えたんだ。そして、「アメリカだけに頼っていてはマズい！」って、西ヨーロッパ諸国が考え始めたんだ。</p>\n<p>こうした動きを受けて、<strong class=\"source-bold\">アメリカもソ連との対話を探り始め</strong>、1959年、ソ連の最高指導者として初めて<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">フルシチョフが訪米</strong></span>し、アメリカ大統領<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">アイゼンハワー</strong></span>と<strong class=\"source-bold\">キャンプ＝デーヴィッド</strong>（アメリカ大統領の山荘）で<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">米ソ首脳会談</strong></span>を実現したんだ。もちろん、重要な問題が解決したわけじゃないんだけど、さまざまな問題を<strong class=\"source-bold\">米ソが協調して話し合いで解決しよう！っていう雰囲気</strong>が生まれた。この時、フルシチョフはアメリカの農場とか工場を視察しているんだけど、「経済力ではアメリカにかなわない……！」って思ったらしい。でも、そんなことピクリとも顔には出さず、フルシチョフはアメリカのテレビの対談番組に出演したりしてるんだ。さすが、スターリンに消されなかっただけあって、役者だな。そして、翌年に<strong class=\"source-bold\">アイゼンハワーがソ連を訪問</strong>することと、パリで<strong class=\"source-bold\">米英仏ソの4国首脳会談</strong>を開催することが決まったんだ。</p>\n<blockquote><p>「雪どけ」は、この米ソ首脳会談がピークだよ。この直後に、状況は一変するよ！</p></blockquote>\n<h3><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">2</span> <span data-source-background=\"pink\" data-source-border=\"red\" style=\"background-color:#f7caca;border:1px solid #e52715;padding:0 0.2em\"><strong class=\"source-bold\">冷戦の再燃とキューバ危機</strong></span></h3>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">◀ キューバ問題、U2型機事件。米ソ関係が悪化するなか、ケネディ大統領が就任！</strong></span></h4>\n<p>1960年代に入ると、「雪どけ」ムードを一気にぶち壊すような事件がいくつも起きて、<strong class=\"source-bold\">米ソ両国は再び対立に逆戻り</strong>した。まず、1960年5月、ソ連の上空で<strong class=\"source-bold\">アメリカのスパイ<ruby>偵察<rt>ていさつ</rt></ruby>機がソ連に撃墜</strong>されるという事件が起きた（<strong class=\"source-bold\">U2型機事件</strong>）。これってソ連にとっては国の威信を揺るがす大事件なんだ。アメリカは、フルシチョフ訪米の前からU2型偵察機をソ連の上空に飛ばして、「<strong class=\"source-bold\">ソ連のミサイルは成功率が低くて、ほとんど配備されてない</strong>」って情報をつかんでいたんだけど、<strong class=\"source-bold\">知らなかったことにして米ソ首脳会談をやった</strong>の。それがソ連にバレちゃった……。完全にメンツを<ruby>潰<rt>つぶ</rt></ruby>されたソ連は、アメリカに謝罪を求めたけど、アイゼンハワーが謝るわけがない。こうして、米ソの対立が再燃して、予定されていた<strong class=\"source-bold\">アイゼンハワー訪ソとパリ首脳会談は中止</strong>になった。</p>\n<p>一方、アメリカにとっての大問題は<strong class=\"source-bold\">キューバ</strong>だよ。1959年、キューバでは<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">カスト</strong></span></p>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">国民国家の形成</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">帝国主義と第一次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦間期と第二次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">戦後の世界</strong></span></p></blockquote>",
  "388": "<h2>388</h2>\n<blockquote><p>388 <span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第21回</strong></span> 冷戦の展開②（1956〜1969）</p></blockquote>\n<p><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ロ</strong></span>や<strong class=\"source-bold\">ゲバラ</strong>を指導者とする<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">キューバ革命</strong></span>が起こり、親米の<strong class=\"source-bold\">バティスタ</strong>軍事政権が倒されて、首相となった<strong class=\"source-bold\">カストロは急激に社会主義に接近</strong>したよ。当時は<ruby>冷戦<rt>れいせん</rt></ruby>の時代だから「アメリカはキライ〜。だから社会主義になる！」って言えば、ソ連が助けてくれるんだ。しかも、キューバってカリブ海（アメリカのすぐ南側）にある島国。<strong class=\"source-bold\">アメリカにとってカリブ海は裏庭</strong>みたいなものだから、<strong class=\"source-bold\">社会主義国をつくらせるわけにはいかない</strong>！ そして、キューバが社会主義的な「土地改革」で、<strong class=\"source-bold\">砂糖生産をしていたアメリカ系企業の土地を没収</strong>すると、アメリカは怒り狂って、ついに1961年1月、<strong class=\"source-bold\">アイゼンハワー大統領はキューバとの断交</strong>を宣言した。この時、アイゼンハワーの任期は残り1カ月もなかったんだ……。</p>\n<p>こんな難しい時期にアメリカ大統領になったのが、<strong class=\"source-bold\">民主党</strong>の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ケネディ</strong></span>だ。彼は共和党のニクソン候補との大統領選挙に勝利して、<strong class=\"source-bold\">史上最年少で大統領に当選</strong>した。アメリカ人は若い大統領に希望を託したんだね。就任演説でケネディは「国があなたのために何ができるかを問うのではなく、あなたが国のために何ができるかを問うてほしい。世界のみなさん、われわれが人類の自由のために、一緒に何ができるかを問うてほしい」と訴え、アメリカが冷戦に勝ち抜く決意を示すとともに、<strong class=\"source-bold\">アメリカの停滞を打破</strong>するために、<strong class=\"source-bold\">科学技術や宇宙開発</strong>などで積極的な経済成長を目指し、そのために教育改革をおこない、さらに<strong class=\"source-bold\">人種や貧困の問題</strong>、要するに黒人の<strong class=\"source-bold\">公民権問題</strong>にも取り組もうとしていた。これらの政策を示すスローガンが<strong class=\"source-bold\">「ニューフロンティア」</strong>だよ。例えば、すでに<strong class=\"source-bold\">ソ連が人類初の有人宇宙飛行に成功</strong>（1961年）していたから、これに対抗して「<strong class=\"source-bold\">アメリカ人を月面に着陸させる</strong>」<strong class=\"source-bold\">アポロ計画を発表</strong>したのはケネディだ。でも、社会主義との対立でそれどころじゃなくなったんだ。</p>\n<blockquote><p>ケネディはアメリカ史上<strong class=\"source-bold\">初のカトリックの大統領</strong>だ。ケネディ家はアイルランド系移民ね</p></blockquote>\n<p>ケネディは<strong class=\"source-bold\">キューバとの断交の方針を変えず</strong>、ラテンアメリカ諸国への経済援助を通じてキューバ革命の波及を阻止する、事実上の反共（反共産主義）同盟<strong class=\"source-bold\">「進歩のための同盟」</strong>を打ち出した。さらにアイゼンハワー政権で計画されていたCIA<strong class=\"source-bold\">による反革命軍のキューバ上陸作戦</strong>（ピッグズ湾事件）を決行したが、この作戦は失敗！、対するキューバでは、カストロが正式に<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">社会主義宣言</strong></span>をおこなった。</p>\n<p>キューバ問題で米ソの対立が深まるなか、さらに関係を悪化させたのが<strong class=\"source-bold\">ベルリン問題</strong>だよ。1961年6月、ケネディとフルシチョフが<strong class=\"source-bold\">ウィーンで米ソ首脳会談</strong>をやったんだけど、ケネディが宇宙開発（という名のミサイル開発）を進めていたことにソ連が反発して、対立は全く収まらなかった。しかも、8月には<strong class=\"source-bold\">東ドイツ</strong>のウルブリヒト政権が、増え続ける<strong class=\"source-bold\">東ドイツから西ドイツへの<ruby>亡命<rt>ぼうめい</rt></ruby>を食い止める</strong>ため、西ベルリンの周囲に「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ベルリンの<ruby>壁<rt>かべ</rt></ruby></strong></span>」を建設し始めた。こんなふうに、ケネディが大統領になってから、米ソ対立はどんどん激しくなったんだよ。</p>",
  "389": "<h2>389</h2>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">2</span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">冷戦の再燃とキューバ危機</u> 389</p></blockquote>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">◀ キューバ危機の「悪夢の13日間」。<ruby>核<rt>かく</rt></ruby>戦争の危機で世界はどうなったんだろう？</strong></span></h4>\n<p>ピッグズ湾で失敗したあとも、<strong class=\"source-bold\">ケネディはキューバへの軍事<ruby>介入<rt>かいにゅう</rt></ruby>を計画</strong>して軍事演習をやっていた。「またアメリカが攻めてくる……」と警戒した<strong class=\"source-bold\">カストロはソ連に軍事援助を頼み</strong>、これに応えたフルシチョフが、アメリカに対抗してキューバに<strong class=\"source-bold\">ソ連のミサイル基地を建設する計画</strong>を立てた。すでにこの時期には、米ソどちらもミサイルの開発に成功していたからね。この動きをキャッチしたケネディは、U2型<ruby>偵<rt>てい</rt></ruby><ruby>察<rt>さつ</rt></ruby>機を飛ばしてキューバへの監視を続けていた。そして、10月に偵察機が撮影した1枚の写真！。<strong class=\"source-bold\">キューバにソ連のミサイル基地建設が進んでいた</strong>んだ。<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">キューバ危機</strong></span>の「<strong class=\"source-bold\">悪夢の13日間</strong>」の始まりだよ……。</p>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td><td></td></tr><tr><td><strong class=\"source-bold\">アメリカ合衆国</strong></td><td><span data-source-color=\"red\" style=\"color:#e52715\">IRBMの最大射程距離</span></td></tr><tr><td>ワシントンD.C.</td><td>ニューヨーク</td></tr><tr><td>ハバナ</td><td><strong class=\"source-bold\">キューバ</strong></td></tr><tr><td><span data-source-color=\"red\" style=\"color:#e52715\">ミサイルなら約15分だ！</span></td><td><span data-source-color=\"red\" style=\"color:#e52715\">MRBMの最大射程距離</span></td></tr></tbody></table></div>\n<p>キューバからミサイルが発射されたら、ワシントンまで約15分……アメリカには<ruby>報復<rt>ほうふく</rt></ruby>する時間もない。ケネディは、ミサイルの持ち込みを阻止するための<strong class=\"source-bold\">海上<ruby>封鎖<rt>ふうさ</rt></ruby></strong>を決め、「<strong class=\"source-bold\">キューバからミサイルが発射されたら、ソ連からの攻撃とみなす</strong>」と演説した。そして、ソ連の輸送船を米軍機が監視するとともに、フロリダに集結した米軍がいつでも出兵可能という異常事態となり、<strong class=\"source-bold\">米ソ両国は開戦寸前</strong>になった。もしこの時、米ソ両国の間に何かの誤解から衝突が起きていたら、米ソの間で核戦争が起きていたかもしれない。しかし、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ケネディ</strong></span>も<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">フルシチョフ</strong></span>もまだ理性を保っていたんだ。ケネディはフルシチョフに「<strong class=\"source-bold\">ソ連がミサイル基地を<ruby>撤去<rt>てっきょ</rt></ruby>すれば、キューバには<ruby>侵攻<rt>しんこう</rt></ruby>しない</strong>」との書簡を送り、これに答えた<strong class=\"source-bold\">フルシチョフ</strong>が、ラジオで「<strong class=\"source-bold\">キューバのミサイル基地撤去を命令</strong>した」と発表したんだ。こうして、スレスレのところで<strong class=\"source-bold\">キューバ危機は回避された</strong>んだ。</p>\n<p>核戦争の危機を実感した<strong class=\"source-bold\">ケネディとフルシチョフ</strong>は、「<strong class=\"source-bold\">米ソの対話を進めるべきだ</strong>」という点で一致したよ。だって、自分の判断一つで世界が滅亡するかもしれなかったんだもん。まずは、緊急事態の際に米ソの首脳が直接話し合えるように、<strong class=\"source-bold\">直通通信回線（米ソホットライン）</strong>を開設することにした。さらに、<strong class=\"source-bold\">核兵器をこれ以上拡散させないため</strong>にも、核実験を制限しなきゃいけないと考えたんだ。そして、1963年8月には米・英・ソの3カ国で<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">部分的核実験禁止条約</strong></span> <strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">PTBT</strong></span>】</strong>が結ばれ、<strong class=\"source-bold\">大気圏内・宇宙空間・水中</strong>での核実験が禁止された。ただ、<strong class=\"source-bold\">地下核実験は禁止じゃなかった</strong>から、核実験そのものが完全になくなったわけじゃない。それに、独自の核開発を進めていた<strong class=\"source-bold\">フランスと中国が不参加</strong>なのも問題だよ。</p>\n<p>歴史に「もしこうなっていたら？」っていうのはないんだけど、もしこのまま米ソが対話を続けていたら、冷戦は違った展開になっていたかもしれない……。でも</p>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">国民国家の形成</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">帝国主義と第一次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦間期と第二次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">戦後の世界</strong></span></p></blockquote>",
  "390": "<h2>390</h2>\n<blockquote><p>390 <span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第21回</strong></span> 冷戦の展開②（1956〜1969）</p></blockquote>\n<p>そうはならなかったんだ。1963年11月、テキサス州の<strong class=\"source-bold\">ダラス</strong>で<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ケネディ大統領が暗殺</strong></span>された！。暗殺の<strong class=\"source-bold\">真相は現在まで不明のまま</strong>だ。一方、ソ連でも1964年に<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">フルシチョフが突然解任</strong></span>された。これって、要するにクーデタだよ……。せっかく対話に向かったのに、米ソの接近はここでいったん挫折しちゃうんだよ。</p>\n<h3>＋<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><em>α</em></strong></span> <u data-source-underline-color=\"black\" style=\"text-decoration-color:#222222\"><strong class=\"source-bold\">ちょっと寄り耳</strong></u></h3>\n<blockquote><p>キューバ危機の時、ケネディはキューバを海上<ruby>封鎖<rt>ふうさ</rt></ruby>したけど、最初はキューバへの海兵隊上陸という選択肢もあったんだ。でもね、この時すでにキューバにはソ連のミサイルが運び込まれていたから、米軍が<ruby>侵攻<rt>しんこう</rt></ruby>していたら、間違いなくソ連はミサイルを発射してただろうね。</p>\n<p>もう一つ、ソ連はキューバのミサイルを<ruby>撤去<rt>てっきょ</rt></ruby>したけど、ウラではもう一つの約束があった。それは、米軍のミサイルをトルコから撤去すること。トルコからミサイルを発射したら、モスクワまで15分。つまり、アメリカにとってのキューバと、ソ連にとってのトルコは同じ条件ってことだ。こんなギリギリの駆け引きが、<ruby>核<rt>かく</rt></ruby>戦争一歩手前でおこなわれていたんだね。</p>\n<p>そして、この重大な決断をしたケネディは、翌年に暗殺された。ケネディ暗殺の瞬間って、映像が残ってるよ。調査報告では、暗殺直後に逮捕されたオズワルドの単独犯ってことになってるけど、映像を見ると弾丸の衝撃で頭が前後に揺れてるから前後から撃たれたんだ。こりゃ単独犯じゃない！ オズワルドも逮捕直後に暗殺されたんだけど、実はCIAのスパイ！。アイゼンハワーが警告していた軍産複合体の暴走？ カストロ？ うーん謎だ。興味があれば、多少の脚色はあるけど、キューバ危機を描いた映画「13デイズ」、ケネディ暗殺を描いた映画「JFK」もあるよ！</p></blockquote>\n<h3><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">3</span> <span data-source-background=\"pink\" data-source-border=\"red\" style=\"background-color:#f7caca;border:1px solid #e52715;padding:0 0.2em\"><strong class=\"source-bold\">ECの成立と西欧諸国</strong></span></h3>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">◀ 世界大戦の教訓からフランスと西ドイツが連携！</strong></span></h4>\n<p>じゃあここで少し話を変えて、<strong class=\"source-bold\">西ヨーロッパの統合</strong>について見ていこう。第二次世界大戦が終わると、戦争で荒れ果てた西ヨーロッパにかわって、<strong class=\"source-bold\">米ソ両大国が国際関係の中心</strong>となり、<strong class=\"source-bold\">ヨーロッパは東西に分断</strong>されてしまった。ヨーロッパ各国は「なんでこんなことになったんだろう？」って考えたんだけど、答えは簡単だよ……。ヨーロッパ全土を巻き込む<strong class=\"source-bold\">世界大戦が2度も起きた</strong>んだもん、没落もするよ。そして2度の世界大戦の原因は、<strong class=\"source-bold\">ドイツとフランスの対立</strong>が大きい。これは、次の戦争を起こさないためにも、<strong class=\"source-bold\">独仏対立を解消</strong>しなきゃいけない！ こうして、フランスを中心にヨーロッパの統合に向けた動きが始まったんだ。</p>",
  "391": "<h2>391</h2>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">3</span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">ECの成立と西欧諸国</u> 391</p></blockquote>\n<h3><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">クローズアップ</strong></span> <span data-source-background=\"pink\" style=\"background-color:#fbe1e1\"><strong class=\"source-bold\">西ヨーロッパの統合（仏・西独・伊・ベネルクス3国の連携）</strong></span></h3>\n<blockquote><p><span data-source-color=\"red\" style=\"color:#e52715\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ヨーロッパ石炭鉄鋼共同体</strong></span> <strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ECSC</strong></span>】</strong>［1951調印／1952発足］</p>\n<p><span data-source-color=\"red\" style=\"color:#e52715\">●</span><strong class=\"source-bold\">ローマ条約</strong>［1957.3］……EEC・<ruby>EURATOM<rt>ユーラトム</rt></ruby>の創設で合意</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ヨーロッパ経済共同体</strong></span> <strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">EEC</strong></span>】</strong>［1958］</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ヨーロッパ原子力共同体</strong></span> <strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">EURATOM</strong></span>】</strong>［1958］</p>\n<p><span data-source-color=\"red\" style=\"color:#e52715\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ヨーロッパ共同体</strong></span> <strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">EC</strong></span>】</strong>［1967.7］……<strong class=\"source-bold\">EEC・ECSC・EURATOMを統合</strong></p></blockquote>\n<p>そうはいっても、いきなり政治的に1つの国になるのは難しいから、まずは資源の共同利用などの経済分野の統合からだ。そして1948年、独仏に挟まれた<strong class=\"source-bold\">ベルギー・オランダ・ルクセンブルク</strong>（この3国が<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ベネルクス3国</strong></span>だ）が<strong class=\"source-bold\">ベネルクス<ruby>関税<rt>かんぜい</rt></ruby>同盟を結成</strong>したのをきっかけに、大本命の西ドイツ・フランスが動いた。フランスは、ドイツを軍事大国にしないためにもヨーロッパの統合が必要だって思ったんだ。</p>\n<blockquote><p>仏・西独・伊って中世のフランク王国、要は「カール大帝の帝国」がもとになった国々だね</p></blockquote>\n<p>そこで、<strong class=\"source-bold\">フランス外相のシューマン</strong>は、これまで独仏両国の対立の原因となってきた<strong class=\"source-bold\">アルザス・ロレーヌの石炭や鉄鉱石</strong>、さらに生産した鉄鋼について、国際機関の管理のもとで共同利用することを西ドイツに提案した（<strong class=\"source-bold\">シューマン＝プラン</strong>）。この構想をもとに、1952年<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ヨーロッパ石炭鉄鋼共同体</strong></span> <strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ECSC</strong></span>】</strong>ができた。加盟国は<strong class=\"source-bold\">フランス、西ドイツ、イタリア</strong>、それに<strong class=\"source-bold\">ベネルクス3国</strong>だ。</p>\n<p>こうして、フランス・西ドイツを中心に協力関係ができると、各国は「戦後<ruby>復興<rt>ふっこう</rt></ruby>のためにも、もっと経済統合を進めよう！」って考えた。だって、<strong class=\"source-bold\">ヨーロッパは米ソ両大国の間に埋もれて存在感が薄くなってる</strong>んだもん。でも、米ソに対抗するには1国じゃ弱い。だったら、「西欧」として世界経済の第三極になればいい！ こうしてECSCを構成する6カ国は、さらに経済統合を進めるための交渉をおこない、1957年には<strong class=\"source-bold\">ローマ条約</strong>を結んで、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ヨーロッパ原子力共同体</strong></span> <strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">EURATOM</strong></span>】</strong>と<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ヨーロッパ経済共同体</strong></span> <strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">EEC</strong></span>】</strong>の創設を決め、<strong class=\"source-bold\">翌年に発足</strong>した。EURATOMでは<strong class=\"source-bold\">原子力エネルギー</strong>（<strong class=\"source-bold\">原子力発電</strong>ね）の共同開発と共同管理をおこない、EECでは、石炭・鉄鋼だけではなく、すべての製品やサービスに拡大して<strong class=\"source-bold\">共通の<ruby>市場<rt>しじょう</rt></ruby></strong>をつくり、EEC加盟国以外に対して<strong class=\"source-bold\">共通の関税</strong>や<strong class=\"source-bold\">貿易政策</strong>をとることにした。これを土台にして加盟各国は50年代に戦後復興を終え、60年代には<strong class=\"source-bold\">フランスや西ドイツは高度経済成長を実現</strong>したよ。</p>\n<p>そして、加盟国が同じ<strong class=\"source-bold\">ECSC・EEC・EURATOMが1つに統合</strong>されて、1967年<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ヨーロッパ共同体</strong></span> <strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">EC</strong></span>】</strong>ができた。ECは、経済だけじゃなくて<strong class=\"source-bold\">将来の政治統合も視野に入れて</strong>いて、貿易の自由化だけでなく、共通のエネルギー・農業・運輸政策、資本と労働力の自由化も進めたんだ。</p>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">国民国家の形成</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">帝国主義と第一次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦間期と第二次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">戦後の世界</strong></span></p></blockquote>",
  "392": "<h2>392</h2>\n<blockquote><p>392 <span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第21回</strong></span> 冷戦の展開②（1956〜1969）</p></blockquote>\n<h3><strong class=\"source-bold\">〈東西両陣営の動揺〉</strong></h3>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td><td></td><td></td></tr><tr><td><strong class=\"source-bold\">フィンランド</strong></td><td><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ノルウェー</strong></span></td><td><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">スウェーデン</strong></span></td></tr><tr><td><strong class=\"source-bold\">アイルランド</strong></td><td><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">イギリス</strong></span></td><td><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">デンマーク</strong></span></td></tr><tr><td><span data-source-border=\"black\" style=\"border:1px solid #001000;padding:0 0.2em\"><strong class=\"source-bold\">オランダ</strong></span></td><td><span data-source-border=\"black\" style=\"border:1px solid #001000;padding:0 0.2em\"><strong class=\"source-bold\">ベルギー</strong></span></td><td><span data-source-border=\"black\" style=\"border:1px solid #001000;padding:0 0.2em\"><strong class=\"source-bold\">ルクセンブルク</strong></span></td></tr><tr><td><span data-source-border=\"black\" style=\"border:1px solid #001000;padding:0 0.2em\"><strong class=\"source-bold\">フランス</strong></span></td><td><span data-source-border=\"black\" style=\"border:1px solid #001000;padding:0 0.2em\"><strong class=\"source-bold\">西ドイツ</strong></span></td><td><strong class=\"source-bold\">東ドイツ</strong></td></tr><tr><td><strong class=\"source-bold\">ポーランド</strong></td><td><strong class=\"source-bold\">チェコスロヴァキア</strong></td><td><strong class=\"source-bold\">ソ連</strong></td></tr><tr><td><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">スイス</strong></span></td><td><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">オーストリア</strong></span></td><td><strong class=\"source-bold\">ハンガリー</strong></td></tr><tr><td><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ポルトガル</strong></span></td><td><strong class=\"source-bold\">スペイン</strong></td><td><span data-source-border=\"black\" style=\"border:1px solid #001000;padding:0 0.2em\"><strong class=\"source-bold\">イタリア</strong></span></td></tr><tr><td><strong class=\"source-bold\">ルーマニア</strong></td><td><strong class=\"source-bold\">ユーゴスラヴィア</strong>（自主路線）</td><td><strong class=\"source-bold\">ブルガリア</strong></td></tr><tr><td><strong class=\"source-bold\">アルバニア</strong></td><td><strong class=\"source-bold\">ギリシア</strong></td><td><strong class=\"source-bold\">トルコ</strong></td></tr><tr><td><span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\">ド＝ゴールがNATO軍事機構脱退［1966］</span></td><td><span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\">ポーランド反政府反ソ暴動［1956］</span></td><td><span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\">「プラハの春」［1968］<br>→ソ連軍、軍事介入</span></td></tr><tr><td><span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\">ハンガリー反ソ暴動［1956］</span></td><td><span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\">チャウシェスクの独自外交［1965〜］</span></td><td><span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\">対ソ断交［1961〜］</span></td></tr><tr><td><span data-source-border=\"black\" style=\"border:1px solid #001000;padding:0 0.2em\"><strong class=\"source-bold\">国名</strong></span> ECの原加盟国</td><td><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">国名</strong></span> EFTAの原加盟国</td><td></td></tr></tbody></table></div>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">◀ EEC加盟を目指すイギリスの前に……ド＝ゴールが立ちはだかった！</strong></span></h4>\n<p><strong class=\"source-bold\">フランスと西ドイツがEECを結成した</strong>のに対抗して、<strong class=\"source-bold\">イギリス</strong>は1960年に<strong class=\"source-bold\">ヨーロッパ自由貿易連合【<ruby>EFTA<rt>エフタ</rt></ruby>】</strong>をつくったよ。これは、<strong class=\"source-bold\">イギリスと北欧3国（デンマーク・ノルウェー・スウェーデン）</strong>、オーストリア、スイス、ポルトガルが、工業製品の貿易を自由化したものだ。ただ、EECに比べて<strong class=\"source-bold\">人口も少ない</strong>し、<strong class=\"source-bold\">工業が弱い</strong>国が多かったから、EECのような経済発展にはつながらなかった。実際、この時期のイギリスは経済力（国民総生産 <strong class=\"source-bold\">【</strong>GNP<strong class=\"source-bold\">】</strong>）で<strong class=\"source-bold\">西ドイツに抜かれ、フランスにも追いつかれた</strong>んだよ。</p>\n<blockquote><p>ECがカール大帝の帝国なら、EFTAはノルマン人の国がもとだね</p></blockquote>\n<p>結局、EFTAでは経済発展を望めないと気づいたイギリスは、「<strong class=\"source-bold\">EECに加盟したい</strong>」って思って加盟申請をしたんだけど、フランスの<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ド＝ゴール</strong></span>が<strong class=\"source-bold\">イギリスの加盟を拒絶</strong>した！。これは、イギリスが加盟すると、イギリスと経済的・軍事的な関係が深い<strong class=\"source-bold\">アメリカにヨーロッパの主導権を握られる</strong>と警戒したからだよ。それに、ド＝ゴールはアメリカがイギリスにだけ<ruby>核<rt>かく</rt></ruby>兵器を提供したのが気に食わなかった。こうして、イギリスの1回目の加盟交渉は失敗したんだ。</p>\n<p>その後、60年代半ばにイギリス経済は深刻な<ruby>不況<rt>ふきょう</rt></ruby>になった。この時期のイギリスは<strong class=\"source-bold\">労働党がつくった福祉国家</strong>が財政を圧迫し、さらに大国としてのプライドから軍</p>",
  "393": "<h2>393</h2>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">3</span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">ECの成立と西欧諸国</u> 393</p></blockquote>\n<p>事費を増やしたために、財政がますます悪化した。そして、1964年に首相となった<strong class=\"source-bold\">労働党</strong>の<strong class=\"source-bold\">ウィルソン</strong>も財政再建を進められず、<strong class=\"source-bold\">ポンド切り下げ</strong>に追い込まれた（<strong class=\"source-bold\">ポンド危機</strong>）。ポンド<ruby>安<rt>やす</rt></ruby>にしたことで一時的には輸出が増えたけど長続きせず、イギリスは経済の停滞から抜け出せなくなって、<strong class=\"source-bold\">「イギリス病」</strong>なんていわれたんだ。さらに、1968年には<strong class=\"source-bold\">スエズ以東から撤兵</strong>して、植民地帝国に終止符を打った。もはや、イギリスには「大国だった昔の想い出」しか残っていないよ。</p>\n<p>こうなると、<strong class=\"source-bold\">残された道はECへの加盟しかない</strong>……。イギリスは1967年に再びEC加盟を申請したんだけど、<strong class=\"source-bold\">またまたド＝ゴールに拒否されて失敗</strong>した。ほんと、ド＝ゴールのイギリス嫌いはスゴイな……。かわいそうに、<strong class=\"source-bold\">ウィルソンはEC加盟の失敗</strong>から総選挙で保守党に負けて、<strong class=\"source-bold\">政権が倒れた</strong>んだよ。</p>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">◀ フランスのド＝ゴールは何を目指していたんだろう？</strong></span></h4>\n<p>じゃあ、こんなにもイギリス嫌い（というかアメリカ嫌い）な<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ド＝ゴール</strong></span>が何を目指していたのか、詳しく解説しよう！ ド＝ゴールが<strong class=\"source-bold\">イギリスのEECへの加盟を断固拒否</strong>し続けたのは、<strong class=\"source-bold\">アメリカとの関係が問題</strong>なんだよ。第二次世界大戦前まで、フランスはイギリスとともにヨーロッパの国際関係の主導権を握っていたけど、大戦の時、あっという間にドイツに<ruby>占領<rt>せんりょう</rt></ruby>されちゃったから<strong class=\"source-bold\">大戦中の首脳会談に出席できず</strong>、国際社会での影が薄くなっていた。さらに、1954年の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ジュネーヴ休戦協定</strong></span>で<strong class=\"source-bold\">ベトナムから撤退</strong>し、その後は独立を求める<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">アルジェリア</strong></span>の抵抗で、泥沼の戦争が続いていた。もはや、かつての大国の面影もなくなっていたんだ。</p>\n<p>こうしたなか、<strong class=\"source-bold\">アルジェリア問題の解決</strong>を期待されて政界に復活した<strong class=\"source-bold\">ド＝ゴール</strong>は、1958年に<strong class=\"source-bold\">大統領権限を強化する憲法改正</strong>を実現した（<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">第五共和政</strong></span>）。大統領になったド＝ゴールは<strong class=\"source-bold\">「フランスの栄光」</strong>をスローガンに大国フランスの復活を目指した。そして、米英を中心とする西側陣営の一員ではなく、<strong class=\"source-bold\">ヨーロッパ統合の中心</strong>になって、<strong class=\"source-bold\">米ソに対抗する第三極</strong>をつくろうとした。これを実現するために「<strong class=\"source-bold\">独自の<ruby>核<rt>かく</rt></ruby>武装</strong>」と、EECを基盤にした「<strong class=\"source-bold\">フランス経済の強化</strong>」を進めたんだ。</p>\n<blockquote><p>フランスの核実験は、イスラエルとの共同実験だったらしい……。国際社会の公然の秘密だけど、イスラエルは核保有国だよ</p></blockquote>\n<p>最初、ド＝ゴールは「<ruby>NATO<rt>ナトー</rt></ruby>の中心を米英仏にしろ」って提案したんだけど、まんまと米英に断られた。「もはや核武装だ！」と思ったド＝ゴールは<strong class=\"source-bold\">サハラ砂漠での</strong><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>原爆<rt>げんばく</rt></ruby>実験</strong></span>に踏みきり、1960年には米英ソに次ぐ4番目の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">核保有国</strong></span>になった。さらに、第三世界の支持を得て米ソに対抗しようと、<strong class=\"source-bold\">植民地の民族運動を支持</strong>して、1960年にはアフリカの植民地14カ国を一気に独立させたんだ（「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">アフリカの年</strong></span>」）。そして1962年には、<strong class=\"source-bold\">民族解放戦線【FLN】</strong>が武力解放闘争を続ける<strong class=\"source-bold\">アルジェリア</strong>に対しても、<strong class=\"source-bold\">エヴィアン協定</strong>で独立を認め、フランス財政の足を引っ張る<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">アルジェリア戦</strong></span></p>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">国民国家の形成</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">帝国主義と第一次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦間期と第二次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">戦後の世界</strong></span></p></blockquote>",
  "394": "<h2>394</h2>\n<blockquote><p>394 <span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第21回</strong></span> 冷戦の展開②（1956〜1969）</p></blockquote>\n<p><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">争</strong></span>を終わらせた。</p>\n<p>ド＝ゴールのアメリカ嫌いはこれだけにとどまらないよ。さっきも話したけど、アメリカとの関係が深い<strong class=\"source-bold\">イギリスのEEC加盟（1967年以降はEC）を拒否</strong>し続けた。さらに、1963年に米英ソが<strong class=\"source-bold\">部分的<ruby>核<rt>かく</rt></ruby>実験禁止条約</strong>を結んで核拡散を止めるために連携すると、1964年には<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">中華人民共和国を承認</strong></span>して、独自の核開発を進める「中仏」の連携で対抗した。さらに1966年にはフランス軍を<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>NATO<rt>ナトー</rt></ruby>軍事機構から脱退</strong></span>させると、<strong class=\"source-bold\">ソ連を訪問</strong>して仏ソの結束をアメリカに見せつけた。そして、西ドイツとともに西ヨーロッパの統合を進め、1967年には<strong class=\"source-bold\">ECを成立させた</strong>よ。こうして、<strong class=\"source-bold\">1960年代のフランスは経済成長を達成</strong>したんだ。</p>\n<p>ただ、ド＝ゴールの<ruby>独裁<rt>どくさい</rt></ruby>的な政治に対する批判が少しずつ拡大していた。1968年にはパリの労働者、学生を中心に<strong class=\"source-bold\">大規模な反ド＝ゴール運動が起きた（五月危機）</strong>。この時は、総選挙でド＝ゴール派が大勝したから一応収まったんだけど、その後も政権に対する不満がくすぶり続けた。「だったら国民投票で決着をつけよう！」とド＝ゴールは<strong class=\"source-bold\">地方自治と議会（上院）改革を問う国民投票</strong>をやったんだけど、結果は敗北……。「だったら辞めてやる」とばかりに<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ド＝ゴールは退陣</strong></span>した。良くも悪くも極端な人だよなぁ。</p>\n<h4><strong class=\"source-bold\">〈1960年代の国際関係〉</strong></h4>\n<div class=\"source-table-wrap\"><table><tbody><tr><td><strong class=\"source-bold\"><span data-source-border=\"black\" style=\"border:1px solid #001000;padding:0 0.2em\">西側陣営</span></strong></td><td><strong class=\"source-bold\"><span data-source-border=\"black\" style=\"border:1px solid #001000;padding:0 0.2em\">東側陣営</span></strong></td></tr><tr><td><strong class=\"source-bold\">米</strong>、<strong class=\"source-bold\">英</strong></td><td><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ソ連</strong></span>、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">東欧諸国</strong></span>、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">中国</strong></span></td></tr><tr><td><span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\"><strong class=\"source-bold\">EC</strong>：<strong class=\"source-bold\">仏</strong>、<strong class=\"source-bold\">西独</strong></span></td><td></td></tr></tbody></table></div>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td><td></td></tr><tr><td><strong class=\"source-bold\">米</strong> ⟷ <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ソ連</strong></span></td><td>冷戦</td></tr><tr><td><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ソ連</strong></span> → <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">東欧諸国</strong></span></td><td><span data-source-color=\"red\" style=\"color:#e52715\">衛星国化</span></td></tr><tr><td><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ソ連</strong></span> ⟷ <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">中国</strong></span></td><td><strong class=\"source-bold\">中ソ対立</strong></td></tr><tr><td><strong class=\"source-bold\">EC</strong> → <strong class=\"source-bold\">英</strong></td><td>対抗</td></tr><tr><td><strong class=\"source-bold\">西独</strong> → <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">東欧諸国</strong></span></td><td><strong class=\"source-bold\">接近（東方外交）</strong> <span data-source-color=\"white\" data-source-background=\"green\" style=\"color:#ffffff;background-color:#859476\">➡P.408</span></td></tr><tr><td><strong class=\"source-bold\">仏</strong> → <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">中国</strong></span></td><td><strong class=\"source-bold\">連携して米ソに対抗</strong><br>（独自の核開発）</td></tr></tbody></table></div>",
  "395": "<h2>395</h2>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">4</span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">東西両陣営の動揺</u> 395</p></blockquote>\n<h3><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">4</span> <span data-source-background=\"pink\" data-source-border=\"red\" style=\"background-color:#f7caca;border:1px solid #e52715;padding:0 0.2em\"><strong class=\"source-bold\">東西両陣営の動揺</strong></span></h3>\n<h4><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">クローズアップ</strong></span> <span data-source-background=\"pink\" style=\"background-color:#fbe1e1\"><strong class=\"source-bold\">ベトナム戦争と世界の多極化［1964〜69］</strong></span></h4>\n<div class=\"source-table-wrap\"><table><tbody><tr><td>〈西側（資本主義）陣営〉</td><td>〈東側（共産主義）陣営〉</td></tr><tr><td><span data-source-color=\"green\" style=\"color:#315837\">●</span>米：<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ジョンソン</strong></span>大統領［在1963〜69］</td><td><span data-source-color=\"green\" style=\"color:#315837\">●</span>ソ連：<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">フルシチョフ失脚</strong></span><br><span data-source-color=\"green\" style=\"color:#315837\">➡</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ブレジネフ</strong></span>第一書記<ruby>就任<rt>しゅうにん</rt></ruby>［1964］</td></tr><tr><td>※仏：<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ド＝ゴール</strong></span>の対米独自路線<br><span data-source-color=\"green\" style=\"color:#315837\">▶</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">中華人民共和国承認</strong></span>［1964］</td><td></td></tr><tr><td><strong class=\"source-bold\">⬇</strong> <span data-source-border=\"black\" style=\"border:1px solid #001000;padding:0 0.2em\"><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ベトナム戦争</strong></span>［1965.2〜］</span></td><td><span data-source-color=\"red\" style=\"color:#e52715\">⬇</span></td></tr><tr><td><span data-source-color=\"green\" style=\"color:#315837\">⬇</span><br>※仏が<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">NATO軍事機構から脱退</strong></span>［1966］<br>※<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ヨーロッパ共同体</strong></span> <strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">EC</strong></span>】</strong>発足［1967］</td><td>※共産圏の動揺<br><span data-source-color=\"green\" style=\"color:#315837\">▶</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ルーマニア独自外交</strong></span>［1965〜］</td></tr><tr><td><span data-source-color=\"red\" style=\"color:#e52715\">⬇</span><br><u data-source-underline-color=\"red\" data-source-underline-style=\"double\" style=\"text-decoration-color:#e52715;text-decoration-style:double\"><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ベトナム反戦運動</strong></span></u>の激化</td><td><span data-source-color=\"red\" style=\"color:#e52715\">⬇</span><br><span data-source-color=\"green\" style=\"color:#315837\">▶</span>「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">プラハの春</strong></span>」（チェコ民主化）［1968］<br><span data-source-color=\"green\" style=\"color:#315837\">▶</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">中ソ国境紛争</strong></span>［1969.3］</td></tr></tbody></table></div>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">◀ ケネディ暗殺で大統領になったジョンソンが、公民権法をつくった！</strong></span></h4>\n<p>じゃあ、米ソに戻るよ！ まずは、<strong class=\"source-bold\">アメリカ国内の問題</strong>から。ケネディ大統領の暗殺で副大統領だった<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ジョンソン</strong></span>が大統領になり、ケネディ路線を引き継いで<strong class=\"source-bold\">人種・<ruby>貧困<rt>ひんこん</rt></ruby>・都市</strong>の問題に取り組んだ。というか、この3つの問題は要するに<strong class=\"source-bold\">黒人問題</strong>なんだよ。人種っていうのは<strong class=\"source-bold\">黒人の公民権問題</strong>、そして貧困層は圧倒的に黒人が多いし、都市の環境や治安の悪化は、貧困層の住んでいるスラムなどの問題でしょ。つまり、<strong class=\"source-bold\">黒人問題に手をつけない限り、この問題は解決しない</strong>んだ。</p>\n<p>とはいっても、アメリカには根深い黒人への差別が残っている。すでに<strong class=\"source-bold\"><ruby>奴隷<rt>どれい</rt></ruby>解放宣言から100年</strong>近くも経っているのに、<strong class=\"source-bold\">ジム＝クロウ制度</strong>（黒人に対する<ruby>隔離<rt>かくり</rt></ruby>政策）はいまだに残っているし……。ただ、状況は少しずつ変わり始めたよ。<strong class=\"source-bold\">第二次世界大戦では多くの黒人が兵士となって<ruby>従軍<rt>じゅうぐん</rt></ruby></strong>したから、彼らは「アメリカ国民」として当たり前の公民権を要求し始めた。これが<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">公民権運動</strong></span>（<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">黒人解放運動</strong></span>）だよ。運動が始まったきっかけは、<strong class=\"source-bold\">公立学校での人種隔離を<ruby>違憲<rt>いけん</rt></ruby></strong>とした1954年の<strong class=\"source-bold\">ブラウン判決</strong>だ。指導者<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">キング牧師</strong></span>は<strong class=\"source-bold\">ガンディーの非暴力主義に影響を受け</strong>、過激な言葉や暴力を使わず、人びとの良心に人種間の対立を乗り越えることを訴えた。そして、</p>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">国民国家の形成</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">帝国主義と第一次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦間期と第二次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">戦後の世界</strong></span></p></blockquote>",
  "396": "<h2>396</h2>\n<blockquote><p>396 <span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第21回</strong></span> 冷戦の展開②（1956〜1969）</p></blockquote>\n<p>徐々に<strong class=\"source-bold\">リベラルな白人の間にも黒人差別に反対する運動が広がり始めた</strong>んだ。</p>\n<p>こうした動きを見たジョンソン大統領は、ケネディ時代には否決された<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">公民権法</strong></span>を議会の抵抗を乗り越えて成立させ、さらに<strong class=\"source-bold\">「偉大な社会」計画</strong>を発表して、「<strong class=\"source-bold\">差別や<ruby>貧困<rt>ひんこん</rt></ruby>をアメリカからなくそう</strong>」って訴え、医療法（高齢者向けのメディケア、貧困層向けのメディケイド）などを制定したよ。ただ、現実にはなかなか差別はなくならなかったから、このあとも<strong class=\"source-bold\">黒人解放運動は続く</strong>よ。</p>\n<h4>＋<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><em>α</em></strong></span> <u data-source-underline-color=\"black\" style=\"text-decoration-color:#222222\"><strong class=\"source-bold\">ちょっと寄り耳</strong></u></h4>\n<blockquote><p>黒人解放運動の指導者キング牧師は、ガンディーに影響を受けた非暴力主義で、アメリカの人種<ruby>偏見<rt>へんけん</rt></ruby>と戦ったよ。まだ無名だった1955年には、アラバマ州でジム＝クロウに反対するバス＝ボイコット運動を成功させて、交通機関での差別に対する<ruby>違憲<rt>いけん</rt></ruby>判決を勝ち取り、一躍有名になった。そして、<ruby>奴隷<rt>どれい</rt></ruby>解放宣言100周年を記念しておこなわれたワシントン大行進で、有名な「I have a dream」の演説をしたんだ。この演説の一節「私には夢がある。いつの日か、ジョージアの赤土の丘の上で、奴隷の息子たちと奴隷主の息子たちが、兄弟のように同じテーブルにつくという夢が」は、ジム＝クロウのもとではありえない「黒人と白人が同じテーブルにつく」ことを“夢”として、人種間の統合の重要性を訴えたものだ。この功績から、1964年にはノーベル平和賞を受賞しているよ。</p>\n<p>ただこののち、黒人解放運動はベトナム反戦運動と結びついてどんどん過激に暴力的になり、1968年のデモ「貧者の行進」を実行中に、キングは暗殺されてしまった。彼は暗殺の前日に死を予言したような演説をしているよ。「私はみなさんと一緒に行けないかもしれないが、1つの民として私たちはきっと約束の地に到達するでしょう……」。</p></blockquote>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">◀ ベトナム戦争が始まって、アメリカの<ruby>威信<rt>いしん</rt></ruby>が大きく揺らいだ！</strong></span></h4>\n<p>続いてアメリカの対外問題だよ。<strong class=\"source-bold\">キューバ危機のあと</strong>、ケネディはソ連との対話を始めると同時に、<strong class=\"source-bold\">南ベトナムに対するアメリカ軍の支援を縮小しよう</strong>と考え始めていたんだけど、その矢先に暗殺されてしまった。かわって大統領になった<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ジョンソン</strong></span>は<strong class=\"source-bold\">ベトナムへの本格<ruby>介入<rt>かいにゅう</rt></ruby></strong>に向かっていくんだ。きっかけは1964年の<strong class=\"source-bold\">トンキン湾事件</strong>なんだけど、その2カ月後には<strong class=\"source-bold\">ソ連でフルシチョフが解任</strong>され、その翌日に<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">中国が<ruby>核<rt>かく</rt></ruby>実験に成功</strong></span>したというニュースが伝わってきた。こうなると、核保有国になった<strong class=\"source-bold\">中国が確実にアジアで影響力を伸ばしてくる</strong>。「ベトナムに本格介入しないと、アジアでのアメリカの威信が大きく揺らぐ」と焦ったジョンソンは、ついに1965年2月<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">北ベトナムへの爆撃</strong></span> <strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>北爆<rt>ほくばく</rt></ruby></strong></span>】</strong>を開始した。こうしてアメリカは<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ベトナム戦争</strong></span>へと突入したんだ。</p>\n<p>戦争の詳細は<span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第24回</strong></span>で話すとして、ここでは<strong class=\"source-bold\">ベトナム戦争がアメリカや国際社会に与えた影響</strong>を見ていくよ。ベトナム戦争は史上初めて、<strong class=\"source-bold\">本格的にテレビで放送さ</strong></p>",
  "397": "<h2>397</h2>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">4</span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">東西両陣営の動揺</u> 397</p></blockquote>\n<p><strong class=\"source-bold\">れた戦争</strong>だ。連日、アメリカ軍が北ベトナムを攻撃する様子が放送され、最初はアメリカ軍目線の放送が多かったけど、そのうちジャーナリストがベトナムに乗り込んで、ベトナム人目線の映像も次々と流され始めた。例えば、アメリカ軍の戦車がベトナムの田んぼのド真ん中を進んでいく映像や、アメリカが支援している南ベトナム兵がおこなった路上処刑の映像などが、テレビを通じて全世界に流されたんだ。</p>\n<p>こうした映像を見た人びとは「<strong class=\"source-bold\">アメリカの正義ってなんなんだよ</strong>？」という疑問を持ったよ。これまでアメリカや西側諸国の大多数の人たちは、<strong class=\"source-bold\">「社会主義＝悪」</strong>、だから社会主義と戦う<strong class=\"source-bold\">「アメリカ＝正義」</strong>だと信じてきた。でも、テレビから流れる映像は<strong class=\"source-bold\">どう見てもアメリカのほうが悪い</strong>！ こうして世界各地で反戦デモが起こり、<strong class=\"source-bold\">アメリカに対する国際的な批判</strong>が強まると、アメリカ国内でも、若者の<ruby>徴兵<rt>ちょうへい</rt></ruby>拒否や反戦デモが起こった。この<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ベトナム反戦運動</strong></span>は、<strong class=\"source-bold\">各国の反体制運動に影響</strong>を与えて、学生や労働者の運動が高揚したよ。特にアメリカでは「体制に反対」する<strong class=\"source-bold\">ベトナム反戦運動と黒人解放運動が結びついて過激になり</strong>、ジョンソン政権の威信は大きく揺らいだんだ。</p>\n<blockquote><p>ヒッピーってこんな感じ。“Love &amp; Peace, yeah!”みたいな</p></blockquote>\n<p>一方で、既存の価値観を崩された<strong class=\"source-bold\">若者たち</strong>は、大人たちが考えないような方法で、体制への不満を爆発させた。<strong class=\"source-bold\">徴兵を拒否</strong>し、「自然と愛と平和」と言って、ギターをかき鳴らして<strong class=\"source-bold\">ロックやフォークソング</strong>を歌い、<strong class=\"source-bold\">ビートルズ</strong>などの音楽に熱狂し、ヒッピー文化も広がった。ジョン＝レノンが“Love &amp; Peace”って言ってたの知ってる？ まぁ、僕もリアルタイムじゃないけどさ。これが、ヒッピーの合言葉だよ。さらに、1968年のウッドストック音楽祭（今のロック・フェスみたいな野外ライブ）には40万人もの若者が殺到したんだけど、ほとんどみんなヒッピーだったらしい……。こうした<strong class=\"source-bold\">若者の反体制文化</strong>が<strong class=\"source-bold\">カウンター＝カルチャー【対抗文化】</strong>だ。あっ……、みんなは「ギター弾いてるだけで、何が反体制なの？」って思うかもしれないけど、当時はギターを持ってるだけで「反抗だ！ 不良だ！」って思われたんだもん！。</p>\n<p>さらに、黒人の公民権運動の影響を受けて、これまでの価値観や思考方法に疑問を持つ人びとも現れて、<strong class=\"source-bold\">さまざまな差別からの解放運動</strong>が盛り上がったんだ。これまで「女性らしさ」といった価値観を押しつけられていた女性は、<strong class=\"source-bold\">性差別に反対するフェミニズム運動</strong>を始めた。また、性的マイノリティの人たちによる<strong class=\"source-bold\">ゲイ・レズビアン解放運動</strong>（最近はLGBTQ＋などと呼ばれるけど、当時はそこまで認識が進んでいなかったためこの呼び方になる）が起きたのもこの時代だよ。また、<strong class=\"source-bold\">大学の権威主義を批判する学生たちによる大学<ruby>紛争<rt>ふんそう</rt></ruby></strong>なども起きたんだ。</p>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">国民国家の形成</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">帝国主義と第一次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦間期と第二次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">戦後の世界</strong></span></p></blockquote>",
  "398": "<h2>398</h2>\n<blockquote><p>398 <span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第21回</strong></span> 冷戦の展開②（1956〜1969）</p></blockquote>\n<p>そして、もっと現実的な意味でアメリカの影響力を弱めたのが、<strong class=\"source-bold\">深刻な財政難</strong>だよ。<strong class=\"source-bold\">ベトナム戦争の軍事費が財政を圧迫</strong>したから、アメリカには世界経済を支える力がなくなった。しかも同じ時期に、<strong class=\"source-bold\">ECや日本が高度経済成長を実現</strong>してアメリカ経済の圧倒的な優位が崩れ、アメリカの地位が揺らぎ始めたんだよ。</p>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">◀ 東欧や中国でソ連への批判が強まり、社会主義陣営が動揺！</strong></span></h4>\n<p>1960年代に入ると、社会主義陣営でも<strong class=\"source-bold\">ソ連に対する批判</strong>がだんだん強まっていたよ。まず、1950年代後半には<strong class=\"source-bold\">ソ連と中国の対立</strong>がかなり深刻になっていた。特に1959年の<strong class=\"source-bold\">フルシチョフ訪米を中国が激しく批判</strong>すると、怒ったソ連は<strong class=\"source-bold\">中ソ技術協定を<ruby>破棄<rt>はき</rt></ruby></strong>して技術者を中国から引き揚げた。さらに<strong class=\"source-bold\">キューバ危機をきっかけに、中ソ対立は頂点に達し</strong>たんだ。中国の<ruby>毛沢東<rt>もうたくとう</rt></ruby>は、ソ連がミサイルを撤去したのは「降伏主義」であり、フルシチョフはアメリカに<ruby>宥和<rt>ゆうわ</rt></ruby>して社会主義から<ruby>逸脱<rt>いつだつ</rt></ruby>する<strong class=\"source-bold\">「修正主義」</strong>者だ！ と、猛烈に批判した。対するソ連は、毛沢東はスターリンのような個人<ruby>独裁<rt>どくさい</rt></ruby>で、世界情勢を理解できない<strong class=\"source-bold\">「<ruby>教条<rt>きょうじょう</rt></ruby>主義」</strong>者だと批判した。さらに<strong class=\"source-bold\">部分的<ruby>核<rt>かく</rt></ruby>実験禁止条約</strong>が<ruby>締結<rt>ていけつ</rt></ruby>されると、中国は「米ソによる中国<ruby>封<rt>ふう</rt></ruby>じ込めだ」と、同じく米ソに対抗して<strong class=\"source-bold\">独自の核開発を進めるフランスに接近</strong>したから、これまで隠されてきた<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">中ソ対立</strong></span>は<strong class=\"source-bold\">公開論争</strong>となり、ついに全世界に知れわたった。その後、中国で<strong class=\"source-bold\">文化大革命が始まると全面対立</strong>になって、話し合いすらできない状態になっちゃった……。この影響で、社会主義陣営は「ソ連と中国の言ってることは、どっちが正しいのか？」をめぐって動揺し、1961年には、中国を支持した<strong class=\"source-bold\">アルバニアがソ連と断交</strong>したんだ。</p>\n<h4><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">合</span><span data-source-color=\"white\" data-source-background=\"brown\" style=\"color:#ffffff;background-color:#a43725\">否</span><strong class=\"source-bold\">の分かれ目</strong>　<strong class=\"source-bold\">独自路線をとった東欧諸国</strong></h4>\n<blockquote><p><span data-source-color=\"brown\" style=\"color:#a43725\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ユーゴスラヴィア</strong></span>……ソ連に<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">コミンフォルムから除名</strong></span>された［1948］</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">▶</span>指導者：<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ティトー</strong></span>のバルカン連邦構想が、ソ連と対立</p></blockquote>\n<blockquote><p><span data-source-color=\"brown\" style=\"color:#a43725\">●</span><strong class=\"source-bold\">アルバニア……中ソ論争で中国を支持</strong></p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">▶</span>指導者：ホジャが<strong class=\"source-bold\">対ソ断交</strong>［1961］。70年代には中国とも対立、<ruby>鎖<rt>さ</rt></ruby><ruby>国<rt>こく</rt></ruby>状態となる</p></blockquote>\n<blockquote><p><span data-source-color=\"brown\" style=\"color:#a43725\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ルーマニア</strong></span>……<strong class=\"source-bold\">コメコンで農業国とされた</strong>ことへの不満が背景</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">▶</span>指導者：<strong class=\"source-bold\">チャウシェスク</strong>は、<strong class=\"source-bold\">石油資源</strong>を背景に<strong class=\"source-bold\">西欧や中国に接近</strong></p></blockquote>",
  "399": "<h2>399</h2>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">4</span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">東西両陣営の動揺</u> 399</p></blockquote>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">◀ フルシチョフの失脚でブレジネフが登場！ 彼はプチ・スターリンか？</strong></span></h4>\n<p>1964年に<strong class=\"source-bold\">フルシチョフが失脚</strong>すると、ソ連の指導者たちはスターリンの死後と同じことを考えた。「結局、スターリン批判をやったフルシチョフに権力が集中してただけじゃん……」。こうしてソ連はまたまた<strong class=\"source-bold\">集団指導体制</strong>となり、第一書記に<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ブレジネフ</strong></span>、首相に<strong class=\"source-bold\">コスイギン</strong>が就任したよ。そして、ブレジネフは<strong class=\"source-bold\">スターリン批判を中止</strong>して、個人独裁ではなく<strong class=\"source-bold\">官僚制の強化</strong>によって政治的な安定を図ったんだ。そして、「何もしないのが良いこと」と言われるくらい、<strong class=\"source-bold\">改革よりも体制の維持が重視された</strong>んだよ。しかし、東欧でソ連支配や独裁体制への批判が噴出して、「何もしない」というわけにいかなくなった。</p>\n<p>まず、ソ連への批判を強めた<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ルーマニアは独自外交</strong></span>を始めたよ。ルーマニアは<strong class=\"source-bold\">コメコン</strong>の国際分業体制で<strong class=\"source-bold\">農業国</strong>にされたんだけど、本当は工業化をしたかったんだ。1965年に政権に<ruby>就<rt>つ</rt></ruby>いた<strong class=\"source-bold\">チャウシェスク</strong>は、「オレの国は石油が出るじゃないか！ もはや、ソ連の言うことなど聞かなくていい！」と、<strong class=\"source-bold\">石油資源を基盤</strong>にして<strong class=\"source-bold\">西欧や中国に接近</strong>した。例えば、1967年には<strong class=\"source-bold\">西ドイツと国交を回復</strong>したよ。あっ、西欧に接近したとはいっても、国内でのチャウシェスクは<strong class=\"source-bold\">秘密警察による恐怖政治</strong>をやるような、ただの独裁者だからね。</p>\n<p>そして、社会主義陣営を大きく揺るがしたのが、1968年に始まった<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">チェコスロヴァキアの民主化</strong></span>だ。1月に第一書記となった<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ドプチェク</strong></span>は<strong class=\"source-bold\">「人間の顔をした社会主義」</strong>を打ち出して、<ruby>検閲<rt>けんえつ</rt></ruby>の廃止・言論の自由化などの民主化を進めたから、チェコスロヴァキアでは共産党以外の政党をつくる動きが起きたり、西欧文化の流入でミニスカートで歩く若者まで現れた。まさに「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">プラハの春</strong></span>」だったんだ。</p>\n<p>しかし、これを見た東欧各国はマジで焦った！。だって、<strong class=\"source-bold\">自分の国に民主化の波が襲ってきたら、共産党の一党独裁体制はあっという間に崩れる</strong>。しかも、この影響はソ連内部にまで波及し始めた。ソ連の<strong class=\"source-bold\">ブレジネフはチェコスロヴァキア（チェコ）に圧力をかけて民主化を<ruby>潰<rt>つぶ</rt></ruby>そうとした</strong>んだけど、ドプチェクは民主化をやめようとしない。ついにブレジネフの怒りが爆発した。1968年8月、50万人にものぼる<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ソ連</strong></span><strong class=\"source-bold\">・東ドイツ・ポーランド・ハンガリー・ブルガリア</strong>5カ国の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ワルシャワ条約機構軍</strong></span>は<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">チェコスロヴァキアに軍事<ruby>介入<rt>かいにゅう</rt></ruby></strong></span>した（<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">チェコ事件</strong></span>）。そして、ドプチェクら改革派は<strong class=\"source-bold\">ソ連に連行</strong>され、<strong class=\"source-bold\">帰国後に解任</strong>された。ただ、チェコの共産党が市民に「武装抵抗をしないように」と呼びかけたから、大きな流血の事態は起きなかったんだ。</p>\n<blockquote><p>独自路線をとっていた「ユーゴスラヴィア・アルバニア・ルーマニア」はチェコへの軍事介入に参加してないよ！</p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">国民国家の形成</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">帝国主義と第一次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦間期と第二次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">戦後の世界</strong></span></p></blockquote>",
  "400": "<h2>400</h2>\n<blockquote><p>400 <span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第21回</strong></span> 冷戦の展開②（1956〜1969）</p></blockquote>\n<h4><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">合</span><span data-source-color=\"white\" data-source-background=\"brown\" style=\"color:#ffffff;background-color:#a43725\">否</span><strong class=\"source-bold\">の分かれ目</strong>　<strong class=\"source-bold\">ソ連の東欧への介入をまとめよう</strong></h4>\n<blockquote><p><span data-source-color=\"brown\" style=\"color:#a43725\">●</span>「スターリン批判」直後［1956］</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ポーランド反政府反ソ暴動</strong></span> <strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ポズナニ暴動</strong></span>】</strong></p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">▶</span>ポーランド軍が<ruby>弾圧<rt>だんあつ</rt></ruby>……<u data-source-underline-color=\"gray\" data-source-underline-style=\"double\" style=\"text-decoration-color:#777777;text-decoration-style:double\"><strong class=\"source-bold\">ソ連軍は<ruby>介入<rt>かいにゅう</rt></ruby>せず</strong></u></p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">➡</span><strong class=\"source-bold\">ゴムウカ</strong>が復活して、ポーランドの自主路線を約束し事態収拾</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ハンガリー反ソ暴動</strong></span> <strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ハンガリー事件</strong></span>】</strong></p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">▶</span>改革派の<strong class=\"source-bold\">ナジ（＝イムレ）</strong>が首相となり、<strong class=\"source-bold\">ワルシャワ条約機構からの脱退</strong>などを声明</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">➡</span><u data-source-underline-color=\"gray\" data-source-underline-style=\"double\" style=\"text-decoration-color:#777777;text-decoration-style:double\"><strong class=\"source-bold\">ソ連軍の全面介入</strong></u>。ナジは逮捕・処刑</p></blockquote>\n<blockquote><p><span data-source-color=\"brown\" style=\"color:#a43725\">●</span>1960年代</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">チェコスロヴァキアの民主化</strong></span>（「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">プラハの春</strong></span>」）［1968］</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">▶</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ドプチェク</strong></span>が自由化運動を推進</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">➡</span><u data-source-underline-color=\"gray\" data-source-underline-style=\"double\" style=\"text-decoration-color:#777777;text-decoration-style:double\"><strong class=\"source-bold\">ソ連軍など5カ国が軍事介入</strong></u>。ドプチェクをソ連に連行、帰国後解任</p></blockquote>\n<p>そして、「プラハの春」とチェコへの軍事介入を経て、<strong class=\"source-bold\">ブレジネフは社会主義陣営とソ連国内への締めつけを強めた</strong>んだ。まず、対外的には<strong class=\"source-bold\">ブレジネフ＝ドクトリン</strong>を発表してチェコへの軍事介入を正当化し、<strong class=\"source-bold\">東欧の制限主権論</strong>、つまり「ソ連は社会主義国の内政に<ruby>干渉<rt>かんしょう</rt></ruby>する権限がある」と主張したんだ。さらに国内では、共産党の<ruby>独裁<rt>どくさい</rt></ruby>体制を強化して、<strong class=\"source-bold\">反体制派を厳しく弾圧</strong>した。スターリンは反対派を殺したけど、ブレジネフは殺すかわりに、「共産党の言ってることが正しいとわからないのは、頭がイカれてる」と言って、病院送りにした。そして病院でヘンなクスリ打って廃人にするの！。どっちがひどいかわからん……これじゃあプチ・スターリンだよ。例えば、<ruby>水爆<rt>すいばく</rt></ruby>開発にかかわったあとに反体制派となった物理学者<strong class=\"source-bold\">サハロフ博士</strong>は、1975年に<strong class=\"source-bold\">ノーベル平和賞</strong>を授賞したけど、その後<ruby>軟禁<rt>なんきん</rt></ruby>されちゃった。</p>\n<p>そして、ソ連が社会主義国への締めつけを強めるのと同じころ、中国では<strong class=\"source-bold\"><ruby>毛沢東<rt>もうたくとう</rt></ruby>が文化大革命で反対派を次々と弾圧</strong>していた。やってることはたいして変わんないんだけど、この両国は「自分が社会主義陣営の中心だ！」と、一歩も譲らない。しかも、<strong class=\"source-bold\">ソ連に反発した社会主義国は中国に接近</strong>したから、ソ連も中国にムカついている。結果、<strong class=\"source-bold\">中ソ対立はますます激しくなって</strong>、ついに<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">中ソ国境紛争</strong></span>にまで発展、1969年には<strong class=\"source-bold\"><ruby>珍宝島<rt>ちんぽうとう</rt></ruby>【ダマンスキー島】</strong>で武力衝突が起きた。こんなふうに、社会主義陣営の動揺をソ連が抑えきれなくなっていたんだね。</p>\n<blockquote><p>中ソ国境紛争は、ソ連が「<ruby>核<rt>かく</rt></ruby>兵器を使おうか」と言い出すほど、激しい対立になったんだ！</p></blockquote>",
  "401": "<h2>401</h2>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">4</span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">東西両陣営の動揺</u> 401</p></blockquote>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">◀ 米ソの支配が弱まって世界の多極化が進み、反体制運動も拡大！</strong></span></h4>\n<p>1960年代の動きをまとめると、一言でいうなら<strong class=\"source-bold\">「米ソの世界支配に限界が見えた時代」</strong>っていうことになるね。<strong class=\"source-bold\">資本主義陣営</strong>では、<strong class=\"source-bold\">フランスがアメリカ支配からの脱却</strong>を狙って、独自の核武装をしたり、仏独を中心とする<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">EC</strong></span>をつくったり、アメリカに対抗して独自路線を歩み始めた。実際、ECに加盟している<strong class=\"source-bold\">フランスや西ドイツは高度経済成長に成功</strong>して、経済的にもアメリカに頼らなくてよくなってきたからね。そして、1960年代のアジアでは<strong class=\"source-bold\">日本が高度経済成長を実現</strong>した。その反面、ベトナム戦争による財政難で、<strong class=\"source-bold\">アメリカは経済的にも地位を低下</strong>させたんだよ。</p>\n<p>そして<strong class=\"source-bold\">社会主義陣営</strong>でも、ソ連の一極支配が揺らいだよね。<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">中ソ対立</strong></span>が始まったことで、社会主義陣営では<strong class=\"source-bold\">ソ連と中国の2国が主導権をめぐって激しく対立</strong>し、その影響で東欧諸国でもソ連の支配から自立しようという動きが起きた。実際に、<strong class=\"source-bold\">アルバニアやルーマニア</strong>は<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">独自外交</strong></span>を展開、すでに独自路線をとっていたユーゴスラヴィアも含めて、ソ連の言うことを聞かない東欧の国が増えたってわけだ。</p>\n<p>こうした東西両陣営の動揺にあわせるように、60年代の後半には資本主義諸国でも<strong class=\"source-bold\">学生や若者などによる反体制運動</strong>が盛り上がったんだ。これは、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ベトナム反戦運動</strong></span>が大きく影響しているよ。アメリカでは<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">黒人解放運動</strong></span>がベトナム反戦運動と結びついて過激化し、フランスでもド＝ゴールの強権政治に対して1968年に<strong class=\"source-bold\">五月危機</strong>が発生、さらに<strong class=\"source-bold\">日本でも学生運動</strong>が起こり、日米安全保障条約の更新反対運動をきっかけに運動が激化、例えば、東大の安田講堂では警官隊と学生の衝突が起きた。そして、社会主義国でも、チェコスロヴァキアの民主化「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">プラハの春</strong></span>」、中国の学生たちによる<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>紅衛兵<rt>こうえいへい</rt></ruby></strong></span>運動も起きた。まあ、中国では紅衛兵は毛沢東の文化大革命に利用されちゃったけどね。</p>\n<p>こうして見てみると、第二次世界大戦後につくられた<ruby>冷戦<rt>れいせん</rt></ruby>構造が、いろいろな面で限界に達していることが明らかになったのが、1960年代ってことだね。</p>\n<p>それじゃあ、今回はこれでおしまい。最後に年号check！</p>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">!!</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">年号</strong></span><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">のツボ</strong></span></h4>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td><td></td></tr><tr><td><span data-source-color=\"red\" style=\"color:#e52715\">●</span><strong class=\"source-bold\">スターリン批判</strong>［<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">1956</strong></span>］</td><td>（スターリンの<ruby>呪縛<rt>じゅばく</rt></ruby>を　<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>解くころ<rt>1 9 5 6</rt></ruby></strong></span>）</td></tr><tr><td><span data-source-color=\"red\" style=\"color:#e52715\">●</span><strong class=\"source-bold\">キューバ危機</strong>［<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">1962</strong></span>］</td><td>（平和への　<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>努力無<rt>1 9 6 2</rt></ruby></strong></span>になる　キューバ危機）</td></tr><tr><td><span data-source-color=\"red\" style=\"color:#e52715\">●</span><strong class=\"source-bold\">部分的核実験禁止条約</strong>［19<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">63</strong></span>］</td><td>（これからやめろ　<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>無残<rt>6 3</rt></ruby></strong></span>な実験）</td></tr><tr><td><span data-source-color=\"red\" style=\"color:#e52715\">●</span><strong class=\"source-bold\"><ruby>北爆<rt>ほくばく</rt></ruby>の開始（ベトナム戦争）</strong>［<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">1965</strong></span>］</td><td>（ベトナム戦争　<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>ひどくむご<rt>1 9 6 5</rt></ruby></strong></span>い）</td></tr><tr><td><span data-source-color=\"red\" style=\"color:#e52715\">●</span><strong class=\"source-bold\">「プラハの春」</strong>［1<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">968</strong></span>］</td><td>（<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>苦労ば<rt>9 6 8</rt></ruby></strong></span>かりの　チェコの民主化）</td></tr></tbody></table></div>\n<p>次回は冷戦の3回目、米ソの世界支配が限界になって、世界の多極化が進み、新たな問題が出てくるよ。いよいよゴールが見えてきたね。最後まで<ruby>頑張<rt>がんば</rt></ruby>ろう！</p>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">国民国家の形成</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">帝国主義と第一次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦間期と第二次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">戦後の世界</strong></span></p></blockquote>",
  "402": "<h2>402</h2>\n<blockquote><p>402 <span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第21回</strong></span> 冷戦の展開②（1956〜1969）</p></blockquote>\n<h3><span data-source-color=\"brown\" style=\"color:#a43725\"><strong class=\"source-bold\">近現代日本へのアプローチ</strong></span> <span data-source-color=\"white\" data-source-background=\"brown\" style=\"color:#ffffff;background-color:#a43725\">8</span></h3>\n<h4><strong class=\"source-bold\">〜安保闘争・沖縄返還と高度経済成長〜</strong></h4>\n<blockquote><p>55年体制のもとで<strong class=\"source-bold\">ソ連との国交回復や国連への加盟</strong>を実現した自民党政権は、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>岸信介<rt>きしのぶすけ</rt></ruby></strong></span>首相が<strong class=\"source-bold\">日米安全保障条約【日米<ruby>安保<rt>あんぽ</rt></ruby>条約】の改定</strong>を目指していたんだ。これは、アメリカとの関係をより対等なものとし、アメリカの日本防衛義務を定めるなど、同盟関係をさらに強化しようとしたんだけど、革新の<strong class=\"source-bold\">社会党が「非武装中立」の立場から激しく反対</strong>して、国会前などで大規模なデモが連日起きたよ（<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">安保闘争</strong></span>）。そして、新条約の自然承認直後に岸内閣は退陣したんだ。その後<strong class=\"source-bold\">ベトナム反戦運動</strong>の影響で、1965年以降、日本でも反戦運動や、大学の権威主義に反対した学生たちによる<strong class=\"source-bold\">大学紛争</strong>も起こり、例えば東大の安田講堂が学生に占拠されて警官隊と衝突する事態にまで発展したんだ。</p>\n<p>同じころ、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>沖縄<rt>おきなわ</rt></ruby></strong></span>ではアメリカの<ruby>統治<rt>とうち</rt></ruby>への不満から<strong class=\"source-bold\">日本への復帰を求める運動</strong>が高まっていた。<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>佐藤栄作<rt>さとうえいさく</rt></ruby></strong></span>首相は<strong class=\"source-bold\">「非<ruby>核<rt>かく</rt></ruby>三原則（核兵器を持たず、作らず、持ち込ませず）」</strong>を明確にしたうえでアメリカ政府と交渉し、1972年に<strong class=\"source-bold\">沖縄の施政権が日本に返還</strong>されたんだ（<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">沖縄返還</strong></span>）。ただ、<strong class=\"source-bold\">沖縄の米軍基地</strong>は、日本に復帰後もあまり縮小されていないよね。</p>\n<p>こうしたなかで、自民党は激しい政治対立を避けるために、国民の関心を経済成長や生活の豊かさに向けさせようとしたんだ。岸内閣のあと首相となった<strong class=\"source-bold\"><ruby>池田<rt>いけだ</rt></ruby><ruby>勇人<rt>はやと</rt></ruby></strong>は<strong class=\"source-bold\">「所得倍増計画」</strong>を打ち出して、減税や公共投資によって経済成長を支援したこともあって、日本は<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">高度経済成長</strong></span>を実現して<strong class=\"source-bold\">GDPがアメリカに次いで世界2位の経済大国になった</strong>。例えば、1964年の<strong class=\"source-bold\">東京オリンピック</strong>にあわせて<strong class=\"source-bold\">東海道新幹線が開通</strong>するなどインフラの整備も進んだよ。そして、1970年に「人類の進歩と調和」をテーマとして開かれた<strong class=\"source-bold\">大阪万博</strong>では、未来の技術としてのワイヤレス電話や、アメリカが月から持ち帰った「月の石」などが展示されたんだ。</p>\n<p>でも、急激な工業化はさまざまな社会問題も浮き彫りにしたんだ。<strong class=\"source-bold\">東京や大阪などの大都市圏に人口が集中</strong>したことで、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">過疎化</strong></span>が進んだ地方との経済格差が広がった。また、排煙による大気汚染、工場排水や生活排水による水質<ruby>汚濁<rt>おだく</rt></ruby>、<ruby>廃棄<rt>はいき</rt></ruby>物の投棄などの<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">公害</strong></span>や<strong class=\"source-bold\">環境破壊が深刻になっていった</strong>んだ。特に<strong class=\"source-bold\"><ruby>水俣<rt>みなまた</rt></ruby>病、<ruby>四日市<rt>よっかいち</rt></ruby>ぜんそく、イタイイタイ病、新潟水俣病</strong>の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">四大公害訴訟</strong></span>に代表される公害反対運動も活発になって、「公害国会」と呼ばれた1970年の臨時国会では、<strong class=\"source-bold\">公害対策基本法</strong>が改正され（制定は1967年）、翌年には<strong class=\"source-bold\">環境庁</strong>（現在は環境省）が設置された。同じころ、世界的にも環境問題が注目され始めて、1972年には<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">国連人間環境会議</strong></span>が開かれたよ。ただ、<strong class=\"source-bold\">1973年の第1次石油危機で世界的に経済が停滞</strong>したこともあって、環境問題に対する世界的な取り組みは停滞してしまうんだ。</p></blockquote>"
};

